import mlx.core as mx

TPB = 256

_kernel = mx.fast.metal_kernel(
    name="row_sum_kernel",
    input_names=["x"],
    output_names=["out"],
    source=f"""
        constexpr uint TPB = {TPB};
        uint tid = thread_position_in_threadgroup.x;
        uint row = threadgroup_position_in_grid.y;
        uint N = threads_per_grid.x; // not used; N passed separately
