        for (uint c = tid; c < n_cols; c += TPB) {{
            partial += x[row * n_cols + c];
        }}
        threadgroup float partials[{TPB}];
        partials[tid] = partial;
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint s = TPB / 2; s > 0; s >>= 1) {{
            if (tid < s) {{
                partials[tid] += partials[tid + s];
            }}
            threadgroup_barrier(mem_flags::mem_threadgroup);
        }}
        if (tid == 0) {{
            out[row] = partials[0];
        }}
    """,
)

